
  import * as fabIcons from './classic/brands.mjs';

  import * as fadIcons from './duotone/solid.mjs';

  import * as fakIcons from './kit/custom.mjs';

  

  import * as faslIcons from './sharp/light.mjs';

  import * as fasrIcons from './sharp/regular.mjs';

  import * as fassIcons from './sharp/solid.mjs';

  import * as fastIcons from './sharp/thin.mjs';


var byPrefixAndName = {'fab': {},'fad': {},'fak': {},'fasl': {},'fasr': {},'fass': {},'fast': {},};
var all = [];

function addIcons (icons) {
  Object.keys(icons).forEach(function (iconName) {
    if (iconName === 'prefix') {
      return;
    }

    var icon = icons[iconName];
    var aliases = icon.icon[2];
    aliases.forEach(function (alias) {
      if (typeof alias === 'string') {
        byPrefixAndName[icon.prefix][alias] = icon;
      }
    })
    byPrefixAndName[icon.prefix][icon.iconName] = icon;
    all.push(icon);
  });
}


  
  addIcons(fabIcons);
  var fab = fabIcons;
  

  
  addIcons(fadIcons);
  var fad = fadIcons;
  

  
  addIcons(fakIcons);
  var fak = fakIcons;
  

  

  
  addIcons(faslIcons);
  var fasl = faslIcons;
  

  
  addIcons(fasrIcons);
  var fasr = fasrIcons;
  

  
  addIcons(fassIcons);
  var fass = fassIcons;
  

  
  addIcons(fastIcons);
  var fast = fastIcons;
  


export {
  byPrefixAndName, all
  , fab, fad, fak, fasl, fasr, fass, fast
}
